const MANIFEST = {
  "type": "Product.ClassicSplit",
  "description": "Classic product page with vertical thumbnails, main image, and product details",
  "editorElement": {
    "selector": ".product-classic-split",
    "displayName": "Product Page - Classic Split",
    "archetype": "container",
    "data": {
      "productBrand": {
        "dataType": "text",
        "displayName": "Brand Name",
        "defaultValue": "Vision Audio",
        "group": "Product Info"
      },
      "productTitle": {
        "dataType": "text",
        "displayName": "Product Title",
        "defaultValue": "Blue Dot (3rd Gen) Smart Speaker",
        "group": "Product Info"
      },
      "productPrice": {
        "dataType": "text",
        "displayName": "Price",
        "defaultValue": "$48.20",
        "group": "Product Info"
      },
      "originalPrice": {
        "dataType": "text",
        "displayName": "Original Price (optional)",
        "defaultValue": "",
        "group": "Product Info"
      },
      "productRating": {
        "dataType": "select",
        "displayName": "Rating",
        "defaultValue": "4.5",
        "options": ["3.0", "3.5", "4.0", "4.5", "5.0"],
        "group": "Product Info"
      },
      "reviewCount": {
        "dataType": "text",
        "displayName": "Review Count",
        "defaultValue": "128",
        "group": "Product Info"
      },
      "productDescription": {
        "dataType": "text",
        "displayName": "Description",
        "defaultValue": "Our most popular smart speaker has a sleek, compact design that fits perfectly into small spaces. It delivers crisp vocals and balanced bass for full sound you can enjoy anywhere in your home.",
        "group": "Product Info"
      },
      "stockStatus": {
        "dataType": "select",
        "displayName": "Stock Status",
        "defaultValue": "inStock",
        "options": ["inStock", "lowStock", "outOfStock"],
        "group": "Product Info"
      },
      "stockCount": {
        "dataType": "text",
        "displayName": "Stock Count",
        "defaultValue": "9",
        "group": "Product Info"
      },
      "color1": {
        "dataType": "color",
        "displayName": "Color Option 1",
        "defaultValue": "#3B82F6",
        "group": "Color Options"
      },
      "color2": {
        "dataType": "color",
        "displayName": "Color Option 2",
        "defaultValue": "#22C55E",
        "group": "Color Options"
      },
      "color3": {
        "dataType": "color",
        "displayName": "Color Option 3",
        "defaultValue": "#EF4444",
        "group": "Color Options"
      },
      "selectedColorName": {
        "dataType": "text",
        "displayName": "Selected Color Name",
        "defaultValue": "Blue",
        "group": "Color Options"
      },
      "material1": {
        "dataType": "text",
        "displayName": "Material Option 1",
        "defaultValue": "Plastic",
        "group": "Material Options"
      },
      "material2": {
        "dataType": "text",
        "displayName": "Material Option 2",
        "defaultValue": "Metal",
        "group": "Material Options"
      },
      "showSpecifications": {
        "dataType": "booleanValue",
        "displayName": "Show Specifications",
        "defaultValue": true,
        "group": "Content"
      },
      "spec1Label": {
        "dataType": "text",
        "displayName": "Spec 1 Label",
        "defaultValue": "Model number",
        "group": "Specifications"
      },
      "spec1Value": {
        "dataType": "text",
        "displayName": "Spec 1 Value",
        "defaultValue": "M46SDCQNA0",
        "group": "Specifications"
      },
      "spec2Label": {
        "dataType": "text",
        "displayName": "Spec 2 Label",
        "defaultValue": "Weight",
        "group": "Specifications"
      },
      "spec2Value": {
        "dataType": "text",
        "displayName": "Spec 2 Value",
        "defaultValue": "980 g",
        "group": "Specifications"
      },
      "spec3Label": {
        "dataType": "text",
        "displayName": "Spec 3 Label",
        "defaultValue": "Dimensions",
        "group": "Specifications"
      },
      "spec3Value": {
        "dataType": "text",
        "displayName": "Spec 3 Value",
        "defaultValue": "120 mm x 24 mm x 62 mm",
        "group": "Specifications"
      },
      "spec4Label": {
        "dataType": "text",
        "displayName": "Spec 4 Label",
        "defaultValue": "Warranty",
        "group": "Specifications"
      },
      "spec4Value": {
        "dataType": "text",
        "displayName": "Spec 4 Value",
        "defaultValue": "1 year",
        "group": "Specifications"
      },
      "showShippingInfo": {
        "dataType": "booleanValue",
        "displayName": "Show Shipping Info",
        "defaultValue": true,
        "group": "Content"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "cardBackground": {
        "dataType": "color",
        "displayName": "Card Background",
        "defaultValue": "#F8F9FA",
        "group": "Colors"
      },
      "titleColor": {
        "dataType": "color",
        "displayName": "Title Color",
        "defaultValue": "#18181B",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#52525B",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent/Button Color",
        "defaultValue": "#18181B",
        "group": "Colors"
      },
      "borderColor": {
        "dataType": "color",
        "displayName": "Border Color",
        "defaultValue": "#E4E4E7",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const [selectedImage, setSelectedImage] = React.useState(0);
  const [selectedColor, setSelectedColor] = React.useState(0);
  const [selectedMaterial, setSelectedMaterial] = React.useState(0);
  const [quantity, setQuantity] = React.useState(1);
  const [specsOpen, setSpecsOpen] = React.useState(true);
  const [shippingOpen, setShippingOpen] = React.useState(false);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const productBrand = config?.productBrand || 'Vision Audio';
  const productTitle = config?.productTitle || 'Blue Dot (3rd Gen) Smart Speaker';
  const productPrice = config?.productPrice || '$48.20';
  const originalPrice = config?.originalPrice || '';
  const productRating = parseFloat(config?.productRating || '4.5');
  const reviewCount = config?.reviewCount || '128';
  const productDescription = config?.productDescription || 'Our most popular smart speaker.';
  const stockStatus = config?.stockStatus || 'inStock';
  const stockCount = config?.stockCount || '9';

  const colors = [
    config?.color1 || '#3B82F6',
    config?.color2 || '#22C55E',
    config?.color3 || '#EF4444'
  ];
  const selectedColorName = config?.selectedColorName || 'Blue';
  const materials = [
    config?.material1 || 'Plastic',
    config?.material2 || 'Metal'
  ];

  const showSpecifications = config?.showSpecifications !== false;
  const specs = [
    { label: config?.spec1Label || 'Model number', value: config?.spec1Value || 'M46SDCQNA0' },
    { label: config?.spec2Label || 'Weight', value: config?.spec2Value || '980 g' },
    { label: config?.spec3Label || 'Dimensions', value: config?.spec3Value || '120 mm x 24 mm x 62 mm' },
    { label: config?.spec4Label || 'Warranty', value: config?.spec4Value || '1 year' }
  ];
  const showShippingInfo = config?.showShippingInfo !== false;

  const backgroundColor = config?.backgroundColor || '#FFFFFF';
  const cardBackground = config?.cardBackground || '#F8F9FA';
  const titleColor = config?.titleColor || '#18181B';
  const textColor = config?.textColor || '#52525B';
  const accentColor = config?.accentColor || '#18181B';
  const borderColor = config?.borderColor || '#E4E4E7';

  // Placeholder images (colored rectangles representing product shots)
  const thumbnails = [0, 1, 2, 3];

  const renderStars = (rating) => {
    const stars = [];
    for (let i = 1; i <= 5; i++) {
      const filled = i <= Math.floor(rating);
      const half = !filled && i === Math.ceil(rating) && rating % 1 !== 0;
      stars.push(
        <span
          key={i}
          style={{
            color: filled || half ? '#FBBF24' : '#E4E4E7',
            fontSize: '14px'
          }}
        >
          ★
        </span>
      );
    }
    return stars;
  };

  const getStockInfo = () => {
    switch (stockStatus) {
      case 'inStock':
        return { text: `${stockCount} in stock`, color: '#22C55E', dot: '#22C55E' };
      case 'lowStock':
        return { text: `Only ${stockCount} left`, color: '#F59E0B', dot: '#F59E0B' };
      case 'outOfStock':
        return { text: 'Out of stock', color: '#EF4444', dot: '#EF4444' };
      default:
        return { text: 'In stock', color: '#22C55E', dot: '#22C55E' };
    }
  };

  const stockInfo = getStockInfo();

  return (
    <div
      className="product-classic-split"
      style={{
        backgroundColor,
        padding: '40px',
        minHeight: '800px'
      }}
    >
      {/* Breadcrumb */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: '8px',
          marginBottom: '24px',
          fontSize: '13px',
          color: textColor
        }}
      >
        <span style={{ cursor: 'pointer' }}>Home</span>
        <span style={{ opacity: 0.5 }}>›</span>
        <span style={{ color: titleColor }}>{productTitle}</span>
      </div>

      {/* Main Content */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: '1fr 1fr',
          gap: '60px',
          maxWidth: '1200px',
          margin: '0 auto'
        }}
      >
        {/* Left: Image Gallery */}
        <div
          style={{
            display: 'flex',
            gap: '16px'
          }}
        >
          {/* Vertical Thumbnails */}
          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              gap: '12px'
            }}
          >
            {thumbnails.map((_, index) => (
              <button
                key={index}
                onClick={() => setSelectedImage(index)}
                style={{
                  width: '64px',
                  height: '64px',
                  borderRadius: '8px',
                  border: selectedImage === index ? `2px solid ${accentColor}` : `1px solid ${borderColor}`,
                  backgroundColor: cardBackground,
                  cursor: 'pointer',
                  padding: '4px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out'
                }}
              >
                <div
                  style={{
                    width: '100%',
                    height: '100%',
                    borderRadius: '4px',
                    backgroundColor: colors[selectedColor],
                    opacity: 0.3 + (index * 0.15)
                  }}
                />
              </button>
            ))}
          </div>

          {/* Main Image */}
          <div
            style={{
              flex: 1,
              position: 'relative',
              backgroundColor: cardBackground,
              borderRadius: '12px',
              aspectRatio: '1',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              overflow: 'hidden'
            }}
          >
            <div
              style={{
                width: '70%',
                height: '70%',
                borderRadius: '20px',
                backgroundColor: colors[selectedColor],
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: '#FFFFFF',
                fontSize: '24px',
                fontWeight: '600',
                letterSpacing: '0.1em',
                boxShadow: '0 20px 40px rgba(0,0,0,0.15)'
              }}
            >
              VISION
            </div>

            {/* Zoom button */}
            <button
              style={{
                position: 'absolute',
                top: '16px',
                right: '16px',
                width: '36px',
                height: '36px',
                borderRadius: '8px',
                backgroundColor: backgroundColor,
                border: `1px solid ${borderColor}`,
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: '16px',
                color: textColor
              }}
              aria-label="Zoom image"
            >
              ⤢
            </button>
          </div>
        </div>

        {/* Right: Product Info */}
        <div>
          {/* Category Badge */}
          <span
            style={{
              display: 'inline-block',
              padding: '4px 12px',
              backgroundColor: cardBackground,
              borderRadius: '4px',
              fontSize: '12px',
              color: textColor,
              marginBottom: '12px'
            }}
          >
            Volume Control
          </span>

          {/* Title */}
          <h1
            style={{
              fontSize: '28px',
              fontWeight: '600',
              color: titleColor,
              margin: '0 0 8px 0',
              lineHeight: '1.3'
            }}
          >
            {productTitle}
          </h1>

          {/* Price */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '8px' }}>
            <span
              style={{
                fontSize: '24px',
                fontWeight: '600',
                color: titleColor
              }}
            >
              {productPrice}
            </span>
            {originalPrice && (
              <span
                style={{
                  fontSize: '16px',
                  color: textColor,
                  textDecoration: 'line-through'
                }}
              >
                {originalPrice}
              </span>
            )}
          </div>

          <p style={{ fontSize: '13px', color: textColor, margin: '0 0 12px 0' }}>
            Tax included. <span style={{ textDecoration: 'underline', cursor: 'pointer' }}>Shipping</span> calculated at checkout.
          </p>

          {/* Rating */}
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '8px',
              marginBottom: '24px',
              paddingBottom: '24px',
              borderBottom: `1px solid ${borderColor}`
            }}
          >
            <div style={{ display: 'flex', gap: '2px' }}>
              {renderStars(productRating)}
            </div>
            <span style={{ fontSize: '14px', color: textColor }}>{productRating}</span>
          </div>

          {/* Color Selection */}
          <div style={{ marginBottom: '20px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
              <span style={{ fontSize: '14px', color: titleColor, fontWeight: '500' }}>
                Color: <span style={{ fontWeight: '400' }}>{selectedColorName}</span>
              </span>
            </div>
            <div style={{ display: 'flex', gap: '10px' }}>
              {colors.map((color, index) => (
                <button
                  key={index}
                  onClick={() => setSelectedColor(index)}
                  style={{
                    width: '32px',
                    height: '32px',
                    borderRadius: '50%',
                    backgroundColor: color,
                    border: selectedColor === index ? '2px solid #18181B' : '2px solid transparent',
                    outline: selectedColor === index ? '2px solid #FFFFFF' : 'none',
                    cursor: 'pointer',
                    transition: prefersReducedMotion ? 'none' : 'all 150ms ease-out'
                  }}
                  aria-label={`Select color ${index + 1}`}
                />
              ))}
            </div>
          </div>

          {/* Material Selection */}
          <div style={{ marginBottom: '20px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
              <span style={{ fontSize: '14px', color: titleColor, fontWeight: '500' }}>
                Material: <span style={{ fontWeight: '400' }}>{materials[selectedMaterial]}</span>
              </span>
              <button
                style={{
                  background: 'none',
                  border: 'none',
                  fontSize: '13px',
                  color: textColor,
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '4px'
                }}
              >
                ✎ Material guide
              </button>
            </div>
            <div style={{ display: 'flex', gap: '10px' }}>
              {materials.map((material, index) => (
                <button
                  key={index}
                  onClick={() => setSelectedMaterial(index)}
                  style={{
                    padding: '10px 20px',
                    borderRadius: '6px',
                    backgroundColor: selectedMaterial === index ? accentColor : backgroundColor,
                    color: selectedMaterial === index ? backgroundColor : titleColor,
                    border: `1px solid ${selectedMaterial === index ? accentColor : borderColor}`,
                    fontSize: '14px',
                    fontWeight: '500',
                    cursor: 'pointer',
                    transition: prefersReducedMotion ? 'none' : 'all 150ms ease-out'
                  }}
                >
                  {material}
                </button>
              ))}
            </div>
          </div>

          {/* Quantity */}
          <div style={{ marginBottom: '16px' }}>
            <span style={{ fontSize: '14px', color: titleColor, fontWeight: '500', display: 'block', marginBottom: '12px' }}>
              Quantity
            </span>
            <div
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                border: `1px solid ${borderColor}`,
                borderRadius: '6px',
                overflow: 'hidden'
              }}
            >
              <button
                onClick={() => setQuantity(Math.max(1, quantity - 1))}
                style={{
                  width: '40px',
                  height: '40px',
                  border: 'none',
                  backgroundColor: 'transparent',
                  fontSize: '18px',
                  color: textColor,
                  cursor: 'pointer'
                }}
              >
                −
              </button>
              <span
                style={{
                  width: '48px',
                  textAlign: 'center',
                  fontSize: '15px',
                  color: titleColor,
                  fontWeight: '500'
                }}
              >
                {quantity}
              </span>
              <button
                onClick={() => setQuantity(quantity + 1)}
                style={{
                  width: '40px',
                  height: '40px',
                  border: 'none',
                  backgroundColor: 'transparent',
                  fontSize: '18px',
                  color: textColor,
                  cursor: 'pointer'
                }}
              >
                +
              </button>
            </div>
          </div>

          {/* Stock Status */}
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '8px',
              marginBottom: '16px'
            }}
          >
            <span
              style={{
                width: '8px',
                height: '8px',
                borderRadius: '50%',
                backgroundColor: stockInfo.dot
              }}
            />
            <span style={{ fontSize: '14px', color: stockInfo.color, fontWeight: '500' }}>
              {stockInfo.text}
            </span>
          </div>

          {/* Action Buttons */}
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: '1fr 1fr',
              gap: '12px',
              marginBottom: '24px'
            }}
          >
            <button
              style={{
                padding: '16px 24px',
                borderRadius: '8px',
                backgroundColor: accentColor,
                color: backgroundColor,
                border: 'none',
                fontSize: '15px',
                fontWeight: '500',
                cursor: 'pointer',
                transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out'
              }}
            >
              Add to cart
            </button>
            <button
              style={{
                padding: '16px 24px',
                borderRadius: '8px',
                backgroundColor: backgroundColor,
                color: titleColor,
                border: `1px solid ${borderColor}`,
                fontSize: '15px',
                fontWeight: '500',
                cursor: 'pointer',
                transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out'
              }}
            >
              Buy it now
            </button>
          </div>

          {/* Shipping Info */}
          {showShippingInfo && (
            <div
              style={{
                display: 'flex',
                flexDirection: 'column',
                gap: '12px',
                marginBottom: '24px',
                paddingBottom: '24px',
                borderBottom: `1px solid ${borderColor}`
              }}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                <span style={{ fontSize: '16px' }}>🚚</span>
                <span style={{ fontSize: '14px', color: textColor }}>Free shipping on all U.S. orders of $40+</span>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                <span style={{ fontSize: '16px' }}>↩️</span>
                <span style={{ fontSize: '14px', color: textColor }}>Free returns and exchanges</span>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                <span style={{ fontSize: '16px' }}>✓</span>
                <span style={{ fontSize: '14px', color: textColor }}>60 night money back guarantee</span>
              </div>
            </div>
          )}

          {/* Description */}
          <p style={{ fontSize: '14px', color: textColor, lineHeight: '1.7', marginBottom: '24px' }}>
            {productDescription}
          </p>

          {/* Specifications Accordion */}
          {showSpecifications && (
            <div style={{ borderTop: `1px solid ${borderColor}` }}>
              <button
                onClick={() => setSpecsOpen(!specsOpen)}
                style={{
                  width: '100%',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                  padding: '16px 0',
                  background: 'none',
                  border: 'none',
                  cursor: 'pointer',
                  fontSize: '15px',
                  fontWeight: '500',
                  color: titleColor
                }}
              >
                Product specifications
                <span style={{
                  transform: specsOpen ? 'rotate(180deg)' : 'rotate(0deg)',
                  transition: prefersReducedMotion ? 'none' : 'transform 200ms ease-out'
                }}>
                  ▾
                </span>
              </button>

              {specsOpen && (
                <div style={{ paddingBottom: '16px' }}>
                  <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                    <tbody>
                      {specs.map((spec, index) => (
                        <tr
                          key={index}
                          style={{
                            borderBottom: `1px solid ${borderColor}`
                          }}
                        >
                          <td style={{ padding: '12px 0', fontSize: '14px', color: textColor }}>
                            {spec.label}
                          </td>
                          <td style={{ padding: '12px 0', fontSize: '14px', color: titleColor, textAlign: 'right' }}>
                            {spec.value}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          )}

          {/* Shipping & Returns Accordion */}
          <div style={{ borderTop: `1px solid ${borderColor}` }}>
            <button
              onClick={() => setShippingOpen(!shippingOpen)}
              style={{
                width: '100%',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                padding: '16px 0',
                background: 'none',
                border: 'none',
                cursor: 'pointer',
                fontSize: '15px',
                fontWeight: '500',
                color: titleColor
              }}
            >
              Shipping & Returns
              <span style={{
                transform: shippingOpen ? 'rotate(180deg)' : 'rotate(0deg)',
                transition: prefersReducedMotion ? 'none' : 'transform 200ms ease-out'
              }}>
                ▾
              </span>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

product-tabbedcontent:
const MANIFEST = {
  "type": "Product.TabbedContent",
  "description": "Product page with image gallery and tabbed description/tech specs",
  "editorElement": {
    "selector": ".product-tabbed-content",
    "displayName": "Product Page - Tabbed Content",
    "archetype": "container",
    "data": {
      "productTitle": {
        "dataType": "text",
        "displayName": "Product Title",
        "defaultValue": "LEATHER CASE FOR AIRPODS PRO",
        "group": "Product Info"
      },
      "productPrice": {
        "dataType": "text",
        "displayName": "Price",
        "defaultValue": "$39.99",
        "group": "Product Info"
      },
      "productRating": {
        "dataType": "select",
        "displayName": "Rating",
        "defaultValue": "5.0",
        "options": ["3.0", "3.5", "4.0", "4.5", "5.0"],
        "group": "Product Info"
      },
      "reviewCount": {
        "dataType": "text",
        "displayName": "Review Count",
        "defaultValue": "1 review",
        "group": "Product Info"
      },
