            <button
              onClick={() => setActiveTab('specs')}
              style={{
                background: 'none',
                border: 'none',
                padding: '12px 0',
                fontSize: '14px',
                fontWeight: '600',
                color: activeTab === 'specs' ? titleColor : textColor,
                cursor: 'pointer',
                borderBottom: activeTab === 'specs' ? `2px solid ${titleColor}` : '2px solid transparent',
                marginBottom: '-1px',
                letterSpacing: '0.05em'
              }}
            >
              TECH SPECS
            </button>
          </div>

          {/* Tab Content */}
          {activeTab === 'description' && (
            <div>
              <h2
                style={{
                  fontSize: '24px',
                  fontWeight: '700',
                  color: titleColor,
                  margin: '0 0 20px 0',
                  fontFamily: 'system-ui, sans-serif'
                }}
              >
                {descriptionTitle}
              </h2>
              <p style={{ fontSize: '15px', color: textColor, lineHeight: '1.8', marginBottom: '24px' }}>
                {descriptionText}
              </p>
              <p style={{ fontSize: '15px', color: textColor, lineHeight: '1.8', marginBottom: '32px' }}>
                We wanted to design something special to house a device that brings us so much joy in our day-to-day lives. As with our entire range of protection, the focus was on how we could add a bit more personality to our everyday carry. Beautiful leather in a timeless finish.
              </p>

              {/* Features List */}
              <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
                {features.map((feature, index) => (
                  <li
                    key={index}
                    style={{
                      display: 'flex',
                      alignItems: 'flex-start',
                      gap: '12px',
                      marginBottom: '16px',
                      fontSize: '15px',
                      color: textColor
                    }}
                  >
                    <span style={{ color: titleColor }}>■</span>
                    {feature}
                  </li>
                ))}
              </ul>
            </div>
          )}

          {activeTab === 'specs' && (
            <div>
              <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                <tbody>
                  {[
                    ['Material', 'Genuine Italian Leather'],
                    ['Compatibility', 'AirPods Pro (1st & 2nd Gen)'],
                    ['Wireless Charging', 'Yes'],
                    ['Dimensions', '54 x 46 x 24 mm'],
                    ['Weight', '15g']
                  ].map(([label, value], index) => (
                    <tr key={index} style={{ borderBottom: `1px solid ${borderColor}` }}>
                      <td style={{ padding: '16px 0', fontSize: '14px', color: textColor }}>{label}</td>
                      <td style={{ padding: '16px 0', fontSize: '14px', color: titleColor, textAlign: 'right' }}>{value}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Bottom Links */}
          <div
            style={{
              display: 'flex',
              gap: '32px',
              marginTop: '40px',
              paddingTop: '24px',
              borderTop: `1px solid ${borderColor}`
            }}
          >
            {[
              { icon: '📦', text: 'Shipping & Returns' },
              { icon: '🛡️', text: 'Warranty' },
              { icon: '🔒', text: 'Secure Payment' }
            ].map((item, index) => (
              <div key={index} style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <span>{item.icon}</span>
                <span style={{ fontSize: '13px', color: textColor }}>{item.text}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Right: Related Products */}
        <div>
          <h3 style={{ fontSize: '16px', fontWeight: '600', color: titleColor, margin: '0 0 20px 0' }}>
            BUY IT WITH
          </h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
            {relatedProducts.map((product, index) => (
              <div
                key={index}
                style={{
                  backgroundColor: cardBackground,
                  borderRadius: '8px',
                  padding: '16px',
                  display: 'flex',
                  flexDirection: 'column'
                }}
              >
                {/* Product Image Placeholder */}
                <div
                  style={{
                    height: '160px',
                    backgroundColor: backgroundColor,
                    borderRadius: '4px',
                    marginBottom: '12px'
                  }}
                />
                <h4 style={{ fontSize: '14px', fontWeight: '500', color: titleColor, margin: '0 0 8px 0' }}>
                  {product.title}
                </h4>
                <p style={{ fontSize: '14px', color: titleColor, margin: '0 0 8px 0' }}>
                  {product.price}
                </p>
                <button
                  style={{
                    background: 'none',
                    border: 'none',
                    padding: 0,
                    fontSize: '13px',
                    color: textColor,
                    cursor: 'pointer',
                    textAlign: 'left',
                    textDecoration: 'underline'
                  }}
                >
                  Quick view
                </button>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

