  const buyNowColor = config?.buyNowColor || '#18181B';
  const borderColor = config?.borderColor || '#E4E4E7';

  const thumbnails = [0, 1, 2, 3, 4];

  return (
    <div
      className="product-compact-quickview"
      style={{
        backgroundColor,
        padding: '40px',
        minHeight: '700px'
      }}
    >
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'auto 1fr 1fr',
          gap: '32px',
          maxWidth: '1100px',
          margin: '0 auto'
        }}
      >
        {/* Left: Vertical Thumbnails with Progress */}
        <div
          style={{
            display: 'flex',
            flexDirection: 'column',
            gap: '12px',
            position: 'relative'
