        >
          {/* Progress Line */}
          <div
            style={{
              position: 'absolute',
              left: '50%',
              top: '0',
              bottom: '0',
              width: '2px',
              backgroundColor: borderColor,
              transform: 'translateX(-50%)',
              zIndex: 0
            }}
          />

          {/* Active Progress */}
          <div
            style={{
              position: 'absolute',
              left: '50%',
              top: '0',
              height: `${((selectedImage + 1) / thumbnails.length) * 100}%`,
              width: '2px',
              backgroundColor: titleColor,
              transform: 'translateX(-50%)',
              zIndex: 1,
              transition: prefersReducedMotion ? 'none' : 'height 300ms ease-out'
            }}
          />

          {thumbnails.map((_, index) => (
            <button
              key={index}
              onClick={() => setSelectedImage(index)}
              style={{
                width: '72px',
                height: '72px',
                borderRadius: '8px',
                border: selectedImage === index ? `2px solid ${titleColor}` : `1px solid ${borderColor}`,
                backgroundColor: backgroundColor,
                cursor: 'pointer',
                padding: '6px',
                position: 'relative',
                zIndex: 2,
                transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out'
              }}
            >
              <div
                style={{
                  width: '100%',
                  height: '100%',
                  borderRadius: '4px',
                  backgroundColor: cardBackground,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center'
                }}
              >
                <div
                  style={{
                    width: '60%',
                    height: '60%',
                    borderRadius: '8px',
                    backgroundColor: accentColor,
                    opacity: 0.3 + (index * 0.15)
                  }}
                />
              </div>
            </button>
          ))}
        </div>

        {/* Center: Main Image */}
        <div
          style={{
            position: 'relative',
            backgroundColor: cardBackground,
            borderRadius: '16px',
            aspectRatio: '1',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center'
          }}
        >
          {/* Placeholder Product */}
          <div
            style={{
              width: '70%',
              height: '50%',
              borderRadius: '16px',
              background: `linear-gradient(135deg, ${accentColor} 0%, ${accentColor}CC 100%)`,
              boxShadow: '0 20px 40px rgba(0,0,0,0.15)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center'
            }}
          >
            <div
              style={{
                width: '30px',
                height: '30px',
                borderRadius: '50%',
                backgroundColor: backgroundColor,
                border: `2px solid ${titleColor}`,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: '14px',
                fontWeight: '600',
                color: titleColor
              }}
            >
              M
            </div>
          </div>

          {/* Next Arrow */}
          <button
            style={{
              position: 'absolute',
              right: '16px',
              top: '50%',
              transform: 'translateY(-50%)',
              width: '40px',
              height: '40px',
              borderRadius: '50%',
              backgroundColor: backgroundColor,
              border: 'none',
              boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
              cursor: 'pointer',
              fontSize: '16px',
              color: textColor
            }}
          >
            ›
          </button>

          {/* Zoom Button */}
          <button
            style={{
              position: 'absolute',
              bottom: '16px',
              right: '16px',
              width: '36px',
              height: '36px',
              borderRadius: '50%',
              backgroundColor: backgroundColor,
              border: 'none',
              boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
              cursor: 'pointer',
              fontSize: '14px',
              color: textColor
            }}
          >
            🔍
          </button>
        </div>

        {/* Right: Product Info */}
        <div style={{ paddingTop: '16px' }}>
          {/* Brand */}
          <p style={{ fontSize: '14px', color: textColor, margin: '0 0 8px 0' }}>
            {productBrand}
          </p>

          {/* Title */}
          <h1
            style={{
              fontSize: '28px',
              fontWeight: '500',
              color: titleColor,
              margin: '0 0 16px 0',
              lineHeight: '1.3',
              fontStyle: 'italic'
            }}
          >
            {productTitle}
          </h1>

          {/* Price & Rating Row */}
          <div
            style={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              marginBottom: '24px'
            }}
          >
            <span style={{ fontSize: '20px', fontWeight: '500', color: titleColor }}>
              {productPrice}
            </span>
            <div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
              <span style={{ fontSize: '14px', color: titleColor }}>{productRating}</span>
              <span style={{ color: '#FBBF24', fontSize: '16px' }}>★</span>
            </div>
          </div>

          {/* Color Selection */}
          <div style={{ marginBottom: '24px' }}>
            <div style={{ fontSize: '14px', color: textColor, marginBottom: '12px' }}>
              Color: <span style={{ color: titleColor }}>{colorName}</span>
            </div>
            <button
              style={{
                width: '32px',
                height: '32px',
                borderRadius: '50%',
                backgroundColor: colorValue,
                border: `2px solid ${titleColor}`,
                cursor: 'pointer',
                outline: `2px solid ${backgroundColor}`,
                outlineOffset: '-4px'
              }}
              aria-label={`Color: ${colorName}`}
            />
          </div>

          {/* Action Buttons */}
          <div style={{ display: 'flex', gap: '12px', marginBottom: '24px' }}>
            <button
              style={{
                flex: 1,
                padding: '16px 24px',
                borderRadius: '8px',
                backgroundColor: accentColor,
                color: '#FFFFFF',
                border: 'none',
                fontSize: '14px',
                fontWeight: '500',
                cursor: 'pointer'
              }}
            >
              Add to cart
            </button>
            <button
              style={{
                flex: 1,
                padding: '16px 24px',
                borderRadius: '30px',
                backgroundColor: buyNowColor,
                color: '#FFFFFF',
                border: 'none',
                fontSize: '14px',
                fontWeight: '500',
                cursor: 'pointer'
              }}
            >
              Buy it now
            </button>
          </div>

          {/* Shipping Banner */}
          {showShippingBanner && (
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '12px',
                padding: '16px',
                backgroundColor: cardBackground,
                borderRadius: '8px',
                marginBottom: '24px'
              }}
            >
              <span style={{ fontSize: '20px' }}>🚚</span>
              <div>
                <div style={{ fontSize: '14px', fontWeight: '600', color: titleColor, marginBottom: '4px' }}>
                  Fast shipping
                </div>
                <div style={{ fontSize: '13px', color: textColor }}>
                  {shippingMessage}
                </div>
              </div>
            </div>
          )}

          {/* View Full Details Link */}
          <button
            style={{
              background: 'none',
              border: 'none',
              padding: 0,
              fontSize: '14px',
              color: titleColor,
              textDecoration: 'underline',
              cursor: 'pointer',
              marginBottom: '16px',
              display: 'block'
            }}
          >
            View full details
          </button>

          {/* Share */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <span style={{ fontSize: '14px', color: textColor }}>↗</span>
            <span style={{ fontSize: '14px', color: textColor }}>Share</span>
          </div>
        </div>
      </div>
    </div>
  );
}

