          style={{
            width: '100%',
            height: '100%',
            objectFit: 'cover'
          }}
        />
        <ImageThumbnails {...props} position="bottom-left" />
      </div>
      <div style={{
        flex: 1,
        padding: '80px 100px',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center'
      }}>
        <ProductInfo {...props} layout="fullscreen" />
      </div>
    </div>
  );
}

// Shared Components
function ImageGallery({ images, currentImage, setCurrentImage, layout, prefersReducedMotion }) {
  return (
    <div style={{ position: 'relative' }}>
      <div style={{
        position: 'relative',
        width: '100%',
        paddingTop: layout === 'magazine' ? '75%' : '125%',
        backgroundColor: '#F1F3F5',
        borderRadius: layout === 'card' ? '8px' : '4px',
        overflow: 'hidden'
      }}>
        {images.map((img, index) => (
          <img
            key={index}
            src={img}
            alt={`Product view ${index + 1}`}
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              opacity: currentImage === index ? 1 : 0,
              transition: prefersReducedMotion ? 'none' : 'opacity 300ms ease-out'
            }}
          />
        ))}
      </div>

      {/* Image navigation dots */}
      {layout !== 'immersive' && (
        <div style={{
          display: 'flex',
          gap: '8px',
          justifyContent: 'center',
          marginTop: '20px'
        }}>
          {images.map((_, index) => (
            <button
              key={index}
              onClick={() => setCurrentImage(index)}
              aria-label={`View image ${index + 1}`}
              style={{
                width: currentImage === index ? '32px' : '8px',
                height: '8px',
                borderRadius: '4px',
                border: 'none',
                backgroundColor: currentImage === index ? '#495057' : '#DEE2E6',
                cursor: 'pointer',
                transition: 'all 250ms ease-out',
                padding: 0
              }}
            />
          ))}
        </div>
      )}
    </div>
  );
}

function ImageThumbnails({ images, currentImage, setCurrentImage, position = "bottom-center" }) {
  const positionStyles = position === "bottom-left" 
    ? { position: 'absolute', bottom: '24px', left: '24px' }
    : { marginTop: '24px', display: 'flex', justifyContent: 'center' };

  return (
    <div style={{
      ...positionStyles,
      display: 'flex',
      gap: '12px',
      zIndex: 10
    }}>
      {images.map((img, index) => (
        <button
          key={index}
          onClick={() => setCurrentImage(index)}
          style={{
            width: '60px',
            height: '60px',
            borderRadius: '4px',
            border: currentImage === index ? '2px solid #FFFFFF' : '2px solid transparent',
            overflow: 'hidden',
            cursor: 'pointer',
            padding: 0,
            opacity: currentImage === index ? 1 : 0.6,
            transition: 'all 200ms ease-out'
          }}
        >
          <img src={img} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
        </button>
      ))}
    </div>
  );
}

function ProductInfo({
  productName,
  productPrice,
  productDescription,
  selectedSize,
  setSelectedSize,
  selectedColor,
  setSelectedColor,
  quantity,
  setQuantity,
  sizes,
  colors,
  ctaText,
  addedToCart,
  handleAddToCart,
  showSizeSelector,
  showColorSelector,
  showQuantitySelector,
  textColor: defaultTextColor,
  secondaryTextColor,
  tertiaryTextColor,
  accentColor,
  buttonTextColor,
  borderColor,
  productNameFontSize,
  productNameFontWeight,
  priceFontSize,
  descriptionFontSize,
  buttonFontSize,
  layout,
  prefersReducedMotion
}) {
  const textColor = defaultTextColor;

  return (
    <div style={{
      animation: prefersReducedMotion ? 'none' : 'slideIn 400ms ease-out 100ms backwards'
    }}>
      <h1 style={{
        fontSize: `${productNameFontSize}px`,
        fontWeight: productNameFontWeight,
        color: textColor,
        margin: '0 0 16px',
        letterSpacing: '0.01em',
        lineHeight: 1.1
      }}>
        {productName}
      </h1>

      <p style={{
        fontSize: `${priceFontSize}px`,
        fontWeight: '500',
        color: textColor,
        margin: '0 0 24px'
      }}>
        ${productPrice}
      </p>

      <p style={{
        fontSize: `${descriptionFontSize}px`,
        lineHeight: 1.6,
        color: layout === 'immersive' ? 'rgba(255,255,255,0.9)' : secondaryTextColor,
        margin: '0 0 32px'
      }}>
        {productDescription}
      </p>

      {/* Color Selector */}
      {showColorSelector && (
        <div style={{ marginBottom: '24px' }}>
          <label style={{
            display: 'block',
            fontSize: '12px',
            fontWeight: '500',
            textTransform: 'uppercase',
            letterSpacing: '0.1em',
            color: layout === 'immersive' ? 'rgba(255,255,255,0.8)' : tertiaryTextColor,
            marginBottom: '12px'
          }}>
            Color
          </label>
          <div style={{ display: 'flex', gap: '12px' }}>
            {colors.map(color => (
              <button
                key={color.name}
                onClick={() => setSelectedColor(color.name)}
                aria-label={`Select ${color.name} color`}
                style={{
                  width: '40px',
                  height: '40px',
                  borderRadius: '50%',
                  backgroundColor: color.hex,
                  border: selectedColor === color.name 
                    ? `3px solid ${textColor}` 
                    : `2px solid ${borderColor}`,
                  cursor: 'pointer',
                  transition: 'all 200ms ease-out',
                  transform: selectedColor === color.name ? 'scale(1.1)' : 'scale(1)'
                }}
              />
            ))}
          </div>
        </div>
      )}

      {/* Size Selector */}
      {showSizeSelector && (
        <div style={{ marginBottom: '24px' }}>
          <label style={{
            display: 'block',
            fontSize: '12px',
            fontWeight: '500',
            textTransform: 'uppercase',
            letterSpacing: '0.1em',
            color: layout === 'immersive' ? 'rgba(255,255,255,0.8)' : tertiaryTextColor,
            marginBottom: '12px'
          }}>
            Size
          </label>
          <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
            {sizes.map(size => (
              <button
                key={size}
                onClick={() => setSelectedSize(size)}
                style={{
                  padding: '12px 20px',
                  backgroundColor: selectedSize === size ? accentColor : 'transparent',
                  color: selectedSize === size ? buttonTextColor : textColor,
                  border: `1px solid ${borderColor}`,
                  borderRadius: '4px',
                  cursor: 'pointer',
                  fontSize: '14px',
                  fontWeight: '500',
                  transition: 'all 200ms ease-out'
                }}
              >
                {size}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Quantity Selector */}
      {showQuantitySelector && (
        <div style={{ marginBottom: '32px' }}>
          <label style={{
            display: 'block',
            fontSize: '12px',
            fontWeight: '500',
            textTransform: 'uppercase',
            letterSpacing: '0.1em',
            color: layout === 'immersive' ? 'rgba(255,255,255,0.8)' : tertiaryTextColor,
            marginBottom: '12px'
          }}>
            Quantity
          </label>
          <div style={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
            <button
              onClick={() => setQuantity(Math.max(1, quantity - 1))}
              style={{
                width: '40px',
                height: '40px',
                backgroundColor: 'transparent',
                border: `1px solid ${borderColor}`,
                borderRadius: '4px',
                cursor: 'pointer',
                fontSize: '18px',
                color: textColor,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                transition: 'all 200ms ease-out'
              }}
            >
              −
            </button>
            <span style={{
              fontSize: '16px',
              fontWeight: '500',
              color: textColor,
              minWidth: '30px',
              textAlign: 'center'
            }}>
              {quantity}
            </span>
            <button
              onClick={() => setQuantity(quantity + 1)}
              style={{
                width: '40px',
                height: '40px',
                backgroundColor: 'transparent',
                border: `1px solid ${borderColor}`,
                borderRadius: '4px',
                cursor: 'pointer',
                fontSize: '18px',
                color: textColor,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                transition: 'all 200ms ease-out'
              }}
            >
              +
            </button>
          </div>
        </div>
      )}

      {/* Add to Cart Button */}
      <button
        onClick={handleAddToCart}
        disabled={addedToCart}
        style={{
          width: '100%',
          padding: '18px 32px',
          backgroundColor: addedToCart ? '#10B981' : accentColor,
          color: buttonTextColor,
          border: 'none',
          borderRadius: '6px',
          fontSize: `${buttonFontSize}px`,
          fontWeight: '500',
          textTransform: 'uppercase',
          letterSpacing: '0.05em',
          cursor: addedToCart ? 'default' : 'pointer',
          transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out',
          position: 'relative',
          overflow: 'hidden'
        }}
      >
        {addedToCart ? (
          <span style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px' }}>
            <svg 
              width="20" 
              height="20" 
              viewBox="0 0 24 24" 
              fill="none" 
              stroke="currentColor" 
              strokeWidth="3"
              style={{
                animation: prefersReducedMotion ? 'none' : 'checkmark 500ms ease-out'
              }}
            >
              <polyline points="20 6 9 17 4 12" />
            </svg>
            Added to Cart
          </span>
        ) : ctaText}
      </button>
    </div>
  );
}

ecommerce-product360:
const MANIFEST = {
  "type": "Ecommerce.Product360",
  "description": "Interactive product card that rotates based on cursor movement.",
  "editorElement": {
    "selector": ".product-360",
    "displayName": "360 Product Card",
    "archetype": "container",
    "data": {
      "productName": { "dataType": "text", "defaultValue": "Aero Sneakers X1", "group": "Content" },
      "price": { "dataType": "text", "defaultValue": "$249.00", "group": "Content" },
      "sensitivity": { "dataType": "select", "defaultValue": "1", "options": ["0.5", "1", "2"], "group": "Interaction" },
      "cardBackground": { "dataType": "color", "defaultValue": "#FFFFFF", "group": "Colors" },
      "accentColor": { "dataType": "color", "defaultValue": "#000000", "group": "Colors" }
    }
  }
};

function Component({ config = {} }) {
  const name = config?.productName || "Aero Sneakers X1";
  const price = config?.price || "$249.00";
  const sensitivity = parseFloat(config?.sensitivity || 1);
  const bg = config?.cardBackground || "#FFFFFF";
  const accent = config?.accentColor || "#000000";

  const [rotation, setRotation] = React.useState(0);
  const cardRef = React.useRef(null);

  const handleMove = (e) => {
    if (!cardRef.current) return;
    const rect = cardRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const percent = x / rect.width;

    // Map 0-1 to 0-360 degrees
    setRotation(percent * 360 * sensitivity);
  };

  return (
    <div style={{ display: 'flex', justifyContent: 'center', padding: '40px', backgroundColor: '#F1F5F9' }}>
      <div 
        ref={cardRef}
        className="product-360"
        onMouseMove={handleMove}
        style={{
          width: '320px',
          padding: '24px',
          borderRadius: '16px',
          backgroundColor: bg,
          boxShadow: '0 20px 40px -10px rgba(0,0,0,0.1)',
          cursor: 'ew-resize',
          userSelect: 'none'
        }}
      >
        {/* 360 VIEWPORT */}
        <div style={{
          height: '250px',
          position: 'relative',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          perspective: '1000px',
          marginBottom: '20px'
        }}>
          {/* SIMULATED 3D OBJECT (Replaceable with Image Sequence) */}
          <div style={{
            width: '150px',
            height: '150px',
            position: 'relative',
            transformStyle: 'preserve-3d',
            transform: `rotateY(${rotation}deg)`,
            // Using direct DOM manipulation for performance would be better, but React state works for simple 3D
          }}>
            {/* Front */}
            <div style={{ position: 'absolute', width: '100%', height: '100%', background: 'linear-gradient(45deg, #FF6B6B, #EE5253)', transform: 'translateZ(75px)', opacity: 0.9, borderRadius: '12px' }} />
            {/* Back */}
            <div style={{ position: 'absolute', width: '100%', height: '100%', background: 'linear-gradient(45deg, #54A0FF, #2E86DE)', transform: 'rotateY(180deg) translateZ(75px)', opacity: 0.9, borderRadius: '12px' }} />
            {/* Right */}
            <div style={{ position: 'absolute', width: '100%', height: '100%', background: 'linear-gradient(45deg, #1DD1A1, #10AC84)', transform: 'rotateY(90deg) translateZ(75px)', opacity: 0.9, borderRadius: '12px' }} />
            {/* Left */}
            <div style={{ position: 'absolute', width: '100%', height: '100%', background: 'linear-gradient(45deg, #FECA57, #FF9F43)', transform: 'rotateY(-90deg) translateZ(75px)', opacity: 0.9, borderRadius: '12px' }} />
          </div>

          {/* 360 Indicator */}
          <div style={{
            position: 'absolute',
            bottom: '10px',
            left: '50%',
            transform: 'translateX(-50%)',
            display: 'flex',
            gap: '8px',
            alignItems: 'center',
            opacity: 0.5
          }}>
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke={accent} strokeWidth="2">
              <path d="M4 12h16M4 12l4-4m-4 4l4 4M20 12l-4-4m4 4l-4 4" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
            <span style={{ fontSize: '10px', fontWeight: '600', color: accent, textTransform: 'uppercase' }}>Drag 360</span>
          </div>
        </div>

        {/* DETAILS */}
        <h3 style={{ fontSize: '20px', fontWeight: '700', color: '#1E293B', margin: '0 0 8px 0' }}>{name}</h3>
        <p style={{ fontSize: '14px', color: '#64748B', margin: '0 0 24px 0', lineHeight: 1.5 }}>
          Engineered for performance. Experience the next generation of comfort.
        </p>

        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span style={{ fontSize: '20px', fontWeight: '600', color: accent }}>{price}</span>
          <button style={{
            padding: '10px 24px',
            backgroundColor: accent,
            color: '#fff',
            border: 'none',
            borderRadius: '8px',
            fontWeight: '600',
            cursor: 'pointer'
          }}>
            Add to Cart
          </button>
        </div>
      </div>
    </div>
  );
}

