        "options": ["ltr", "rtl"],
        "group": "Advanced"
      },
      "categoriesData": {
        "dataType": "text",
        "displayName": "Categories Data (JSON)",
        "defaultValue": "[{\"title\":\"Electronics\",\"subtitle\":\"Latest gadgets and tech\",\"tag\":\"NEW\",\"count\":156,\"button\":\"Shop Now\",\"image\":\"https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=600\",\"size\":\"featured\"},{\"title\":\"Fashion\",\"subtitle\":\"Trending styles\",\"tag\":\"SALE\",\"count\":89,\"button\":\"Explore\",\"image\":\"https://images.unsplash.com/photo-1558171813-4c088753af8f?w=600\",\"size\":\"medium\"},{\"title\":\"Home & Living\",\"subtitle\":\"Comfort essentials\",\"count\":234,\"button\":\"Browse\",\"image\":\"https://images.unsplash.com/photo-1556909114-f6e7ad7d3136?w=600\",\"size\":\"medium\"},{\"title\":\"Sports\",\"subtitle\":\"Gear up for adventure\",\"tag\":\"HOT\",\"count\":67,\"button\":\"Shop Now\",\"image\":\"https://images.unsplash.com/photo-1461896836934- voices8a8a08?w=600\",\"size\":\"small\"},{\"title\":\"Beauty\",\"subtitle\":\"Skincare & cosmetics\",\"count\":145,\"button\":\"Discover\",\"image\":\"https://images.unsplash.com/photo-1596462502278-27bfdc403348?w=600\",\"size\":\"wide\"},{\"title\":\"Books\",\"subtitle\":\"Expand your mind\",\"count\":312,\"button\":\"Read More\",\"image\":\"https://images.unsplash.com/photo-1512820790803-83ca734da794?w=600\",\"size\":\"small\"}]",
        "group": "Content",
        "description": "JSON array of categories. Each item: title, subtitle, tag, count, button, image, size (small/medium/wide/tall/featured)"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const [hoveredIndex, setHoveredIndex] = React.useState(null);
  const [mounted, setMounted] = React.useState(false);
  const [carouselPosition, setCarouselPosition] = React.useState(0);
  const carouselRef = React.useRef(null);

  const prefersReducedMotion = typeof window !== 'undefined' 
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches 
    : false;

  // Parse config with safe defaults
  const displayMode = config?.displayMode || 'grid';
  const columns = parseInt(config?.columns || '3');
  const gap = parseInt(config?.gap || '16');
  const cardHeight = config?.cardHeight || '320';
  const cardBorderRadius = parseInt(config?.cardBorderRadius || '12');
  const cardLayout = config?.cardLayout || 'overlay';
  const imageSplit = parseInt(config?.imageSplit || '50');
  const contentPosition = config?.contentPosition || 'bottom-left';
  const contentPadding = parseInt(config?.contentPadding || '24');
  const imageObjectFit = config?.imageObjectFit || 'cover';
  const imageObjectPosition = (config?.imageObjectPosition || 'center').replace('-', ' ');

  const showOverlay = config?.showOverlay !== false;
  const overlayType = config?.overlayType || 'gradient-bottom';
  const overlayColor = config?.overlayColor || '#000000';
  const overlayOpacity = parseFloat(config?.overlayOpacity || '0.5');
  const overlayGradientEnd = config?.overlayGradientEnd || '#1a1a2e';

  const patternType = config?.patternType || 'none';
  const patternColor = config?.patternColor || '#000000';
  const patternOpacity = parseFloat(config?.patternOpacity || '0.08');
  const patternSize = config?.patternSize || 'medium';

  const cardBackgroundColor = config?.cardBackgroundColor || '#F8F9FA';
  const containerBackgroundColor = config?.containerBackgroundColor || '#FFFFFF';
  const titleColor = config?.titleColor || '#FFFFFF';
  const subtitleColor = config?.subtitleColor || '#E9ECEF';
  const tagBackgroundColor = config?.tagBackgroundColor || '#212529';
  const tagTextColor = config?.tagTextColor || '#FFFFFF';
  const countColor = config?.countColor || '#ADB5BD';
  const buttonBackgroundColor = config?.buttonBackgroundColor || '#FFFFFF';
  const buttonTextColor = config?.buttonTextColor || '#212529';
  const buttonHoverBackgroundColor = config?.buttonHoverBackgroundColor || '#212529';
  const buttonHoverTextColor = config?.buttonHoverTextColor || '#FFFFFF';
  const cardBorderColor = config?.cardBorderColor || '#E9ECEF';

  const titleFontFamily = config?.titleFontFamily || 'Inter';
  const titleFontSize = parseInt(config?.titleFontSize || '24');
  const titleFontWeight = config?.titleFontWeight || '500';
  const titleLetterSpacing = config?.titleLetterSpacing || '0em';
  const titleTextTransform = config?.titleTextTransform || 'none';
  const subtitleFontSize = parseInt(config?.subtitleFontSize || '14');
  const subtitleFontWeight = config?.subtitleFontWeight || '400';
  const tagFontSize = parseInt(config?.tagFontSize || '11');
  const tagTextTransform = config?.tagTextTransform || 'uppercase';
  const buttonFontSize = parseInt(config?.buttonFontSize || '14');
  const buttonTextTransform = config?.buttonTextTransform || 'none';

  const showTag = config?.showTag !== false;
  const showSubtitle = config?.showSubtitle !== false;
  const showProductCount = config?.showProductCount !== false;
  const showButton = config?.showButton !== false;
  const buttonStyle = config?.buttonStyle || 'filled';
  const buttonBorderRadius = parseInt(config?.buttonBorderRadius || '6');
  const buttonPaddingH = parseInt(config?.buttonPaddingH || '20');
  const buttonPaddingV = parseInt(config?.buttonPaddingV || '10');

  const cardHoverEffect = config?.cardHoverEffect || 'lift-shadow';
  const imageHoverEffect = config?.imageHoverEffect || 'zoom';
  const imageHoverScale = parseFloat(config?.imageHoverScale || '1.1');
  const overlayHoverEffect = config?.overlayHoverEffect || 'darken';
  const contentHoverEffect = config?.contentHoverEffect || 'slide-up';
  const subtitleHidden = config?.subtitleHidden === true;
  const buttonHidden = config?.buttonHidden === true;

  const transitionDuration = parseInt(config?.transitionDuration || '400');
  const transitionEasing = config?.transitionEasing || 'cubic-bezier(0.22, 1, 0.36, 1)';
  const staggerDelay = parseInt(config?.staggerDelay || '50');
  const entranceAnimation = config?.entranceAnimation || 'fade-up';

  const carouselShowArrows = config?.carouselShowArrows !== false;
  const carouselShowDots = config?.carouselShowDots === true;
  const carouselCardWidth = parseInt(config?.carouselCardWidth || '280');
  const carouselAutoPlay = config?.carouselAutoPlay === true;

  const textDirection = config?.textDirection || 'ltr';
  const isRTL = textDirection === 'rtl';

  // Parse categories data
  const categories = React.useMemo(() => {
    try {
      const parsed = JSON.parse(config?.categoriesData || '[]');
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }, [config?.categoriesData]);

  // Entrance animation
  React.useEffect(() => {
    const timer = setTimeout(() => setMounted(true), 100);
    return () => clearTimeout(timer);
  }, []);

  // Generate pattern CSS
  const getPatternCSS = (type, color, size) => {
    const sizeMap = { small: 10, medium: 20, large: 40, xlarge: 80 };
    const s = sizeMap[size] || 20;
    const c = color;

    const patterns = {
      'dots': `radial-gradient(${c} 1px, transparent 1px)`,
      'grid': `linear-gradient(${c} 1px, transparent 1px), linear-gradient(90deg, ${c} 1px, transparent 1px)`,
      'diagonal': `repeating-linear-gradient(45deg, ${c} 0, ${c} 1px, transparent 0, transparent 50%)`,
      'diagonal-reverse': `repeating-linear-gradient(-45deg, ${c} 0, ${c} 1px, transparent 0, transparent 50%)`,
      'crosshatch': `repeating-linear-gradient(45deg, ${c} 0, ${c} 1px, transparent 0, transparent 50%), repeating-linear-gradient(-45deg, ${c} 0, ${c} 1px, transparent 0, transparent 50%)`,
      'horizontal': `repeating-linear-gradient(0deg, ${c} 0, ${c} 1px, transparent 0, transparent ${s}px)`,
      'vertical': `repeating-linear-gradient(90deg, ${c} 0, ${c} 1px, transparent 0, transparent ${s}px)`,
      'checkerboard': `repeating-conic-gradient(${c} 0% 25%, transparent 0% 50%)`,
      'triangles': `linear-gradient(135deg, ${c} 25%, transparent 25%) -${s/2}px 0, linear-gradient(225deg, ${c} 25%, transparent 25%) -${s/2}px 0, linear-gradient(315deg, ${c} 25%, transparent 25%), linear-gradient(45deg, ${c} 25%, transparent 25%)`,
      'hexagons': `radial-gradient(circle farthest-side at 0% 50%, ${c} 23.5%, transparent 0) ${s*1.05}px ${s*1.82}px, radial-gradient(circle farthest-side at 0% 50%, ${c} 24%, transparent 0) ${s*0.525}px ${s*0.91}px`,
      'zigzag': `linear-gradient(135deg, ${c} 25%, transparent 25%) -${s}px 0, linear-gradient(225deg, ${c} 25%, transparent 25%) -${s}px 0, linear-gradient(315deg, ${c} 25%, transparent 25%), linear-gradient(45deg, ${c} 25%, transparent 25%)`,
      'diamond': `linear-gradient(135deg, ${c} 25%, transparent 25%), linear-gradient(225deg, ${c} 25%, transparent 25%), linear-gradient(45deg, ${c} 25%, transparent 25%), linear-gradient(315deg, ${c} 25%, transparent 25%)`,
      'plus': `linear-gradient(${c} 2px, transparent 2px), linear-gradient(90deg, ${c} 2px, transparent 2px)`,
      'brick': `linear-gradient(335deg, ${c} 23px, transparent 23px), linear-gradient(155deg, ${c} 23px, transparent 23px)`,
      'polka-large': `radial-gradient(${c} ${s/4}px, transparent ${s/4}px)`,
      'circuit': `radial-gradient(${c} 1px, transparent 1px), linear-gradient(90deg, transparent 45%, ${c} 45%, ${c} 55%, transparent 55%)`,
      'waves': `radial-gradient(ellipse 100% 50% at 50% 50%, transparent 45%, ${c} 48%, ${c} 52%, transparent 55%)`,
      'herringbone': `linear-gradient(135deg, ${c} 10%, transparent 10%), linear-gradient(225deg, ${c} 10%, transparent 10%)`,
      'gentle-curves': `radial-gradient(ellipse 80% 40% at 50% 100%, transparent 70%, ${c} 100%)`,
      'flowing-waves': `radial-gradient(ellipse 100% 100% at 50% 0%, transparent 60%, ${c} 100%)`,
      'topographic': `repeating-radial-gradient(circle at 50% 50%, transparent 0, transparent ${s}px, ${c} ${s}px, ${c} ${s+1}px)`,
      'fingerprint': `repeating-radial-gradient(circle at 50% 50%, transparent 0, transparent ${s/2}px, ${c} ${s/2}px, ${c} ${s/2+1}px)`,
      'ocean-ripples': `repeating-radial-gradient(circle at 0% 100%, transparent 0, transparent ${s}px, ${c} ${s}px, ${c} ${s+1}px)`,
      'zen-garden': `repeating-radial-gradient(circle at 100% 0%, transparent 0, transparent ${s}px, ${c} ${s}px, ${c} ${s+0.5}px)`,
      'contour-map': `repeating-radial-gradient(ellipse 80% 60% at 50% 50%, transparent 0, transparent ${s}px, ${c} ${s}px, ${c} ${s+0.5}px)`,
      'moire': `repeating-radial-gradient(circle at 50% 50%, transparent 0, transparent 3px, ${c} 3px, ${c} 4px), repeating-radial-gradient(circle at 55% 45%, transparent 0, transparent 3px, ${c} 3px, ${c} 4px)`
    };

    return patterns[type] || 'none';
  };

  const getPatternSizeCSS = (type, size) => {
    const sizeMap = { small: 10, medium: 20, large: 40, xlarge: 80 };
    const s = sizeMap[size] || 20;

    if (['dots', 'polka-large', 'grid', 'plus'].includes(type)) {
      return `${s}px ${s}px`;
    }
    if (['diagonal', 'diagonal-reverse', 'crosshatch'].includes(type)) {
      return `${s}px ${s}px`;
    }
    if (type === 'checkerboard') {
      return `${s}px ${s}px`;
    }
    if (['triangles', 'diamond', 'zigzag'].includes(type)) {
      return `${s}px ${s}px`;
    }
    return `${s * 2}px ${s * 2}px`;
  };

  // Generate overlay CSS
  const getOverlayCSS = (type, color, opacity, gradientEnd, isHovered) => {
    const baseOpacity = isHovered && overlayHoverEffect === 'darken' 
      ? Math.min(opacity + 0.3, 1) 
      : isHovered && overlayHoverEffect === 'lighten'
        ? Math.max(opacity - 0.2, 0)
        : opacity;

    const rgba = (hex, a) => {
      const r = parseInt(hex.slice(1, 3), 16);
      const g = parseInt(hex.slice(3, 5), 16);
      const b = parseInt(hex.slice(5, 7), 16);
      return `rgba(${r}, ${g}, ${b}, ${a})`;
    };

    switch (type) {
      case 'solid':
        return { background: rgba(color, baseOpacity) };
      case 'gradient-bottom':
        return { background: `linear-gradient(to top, ${rgba(color, baseOpacity)} 0%, ${rgba(gradientEnd, baseOpacity * 0.3)} 50%, transparent 100%)` };
      case 'gradient-top':
        return { background: `linear-gradient(to bottom, ${rgba(color, baseOpacity)} 0%, ${rgba(gradientEnd, baseOpacity * 0.3)} 50%, transparent 100%)` };
      case 'gradient-left':
        return { background: `linear-gradient(to right, ${rgba(color, baseOpacity)} 0%, ${rgba(gradientEnd, baseOpacity * 0.3)} 50%, transparent 100%)` };
      case 'gradient-right':
        return { background: `linear-gradient(to left, ${rgba(color, baseOpacity)} 0%, ${rgba(gradientEnd, baseOpacity * 0.3)} 50%, transparent 100%)` };
      case 'gradient-radial':
        return { background: `radial-gradient(circle at center, transparent 0%, ${rgba(color, baseOpacity)} 100%)` };
      case 'gradient-diagonal':
        return { background: `linear-gradient(135deg, ${rgba(color, baseOpacity)} 0%, transparent 50%, ${rgba(gradientEnd, baseOpacity * 0.5)} 100%)` };
      default:
        return { background: rgba(color, baseOpacity) };
    }
  };

  // Get content alignment styles
  const getContentAlignment = (position) => {
    const alignments = {
      'top-left': { justifyContent: 'flex-start', alignItems: 'flex-start', textAlign: 'left' },
      'top-center': { justifyContent: 'flex-start', alignItems: 'center', textAlign: 'center' },
      'top-right': { justifyContent: 'flex-start', alignItems: 'flex-end', textAlign: 'right' },
      'center-left': { justifyContent: 'center', alignItems: 'flex-start', textAlign: 'left' },
      'center': { justifyContent: 'center', alignItems: 'center', textAlign: 'center' },
      'center-right': { justifyContent: 'center', alignItems: 'flex-end', textAlign: 'right' },
      'bottom-left': { justifyContent: 'flex-end', alignItems: 'flex-start', textAlign: 'left' },
      'bottom-center': { justifyContent: 'flex-end', alignItems: 'center', textAlign: 'center' },
      'bottom-right': { justifyContent: 'flex-end', alignItems: 'flex-end', textAlign: 'right' }
    };
    return alignments[position] || alignments['bottom-left'];
  };

  // Get card hover styles
  const getCardHoverStyles = (isHovered) => {
    if (!isHovered || prefersReducedMotion) return {};

    switch (cardHoverEffect) {
      case 'lift':
        return { transform: 'translateY(-8px)' };
      case 'lift-shadow':
        return { transform: 'translateY(-8px)', boxShadow: '0 20px 40px rgba(0,0,0,0.15)' };
      case 'scale':
        return { transform: 'scale(1.03)' };
      case 'scale-down':
        return { transform: 'scale(0.97)' };
      case 'border-glow':
        return { boxShadow: `0 0 20px ${cardBorderColor}` };
      case 'border-color':
        return { borderColor: titleColor };
      default:
        return {};
    }
  };

  // Get image hover styles
  const getImageHoverStyles = (isHovered) => {
    if (!isHovered || prefersReducedMotion) return {};

    switch (imageHoverEffect) {
      case 'zoom':
        return { transform: `scale(${imageHoverScale})` };
      case 'zoom-out':
        return { transform: 'scale(0.9)' };
      case 'zoom-rotate':
        return { transform: `scale(${imageHoverScale}) rotate(3deg)` };
      case 'pan-left':
        return { transform: 'translateX(-10%)' };
      case 'pan-right':
        return { transform: 'translateX(10%)' };
      case 'pan-up':
        return { transform: 'translateY(-10%)' };
      case 'pan-down':
        return { transform: 'translateY(10%)' };
      case 'blur-sharpen':
        return { filter: 'blur(0)' };
      case 'grayscale-color':
        return { filter: 'grayscale(0)' };
      case 'brighten':
        return { filter: 'brightness(1.2)' };
      case 'darken':
        return { filter: 'brightness(0.8)' };
      case 'saturate':
        return { filter: 'saturate(1.5)' };
      default:
        return {};
    }
  };

  // Get image base styles (for hover-out state)
  const getImageBaseStyles = () => {
    switch (imageHoverEffect) {
      case 'blur-sharpen':
        return { filter: 'blur(3px)' };
      case 'grayscale-color':
        return { filter: 'grayscale(100%)' };
      default:
        return {};
    }
  };

  // Get entrance animation styles
  const getEntranceStyles = (index) => {
    if (entranceAnimation === 'none' || prefersReducedMotion) {
      return { opacity: 1, transform: 'none' };
    }

    const delay = index * staggerDelay;
    const notMounted = !mounted;

    const animations = {
      'fade': { opacity: notMounted ? 0 : 1 },
      'fade-up': { opacity: notMounted ? 0 : 1, transform: notMounted ? 'translateY(30px)' : 'translateY(0)' },
      'fade-down': { opacity: notMounted ? 0 : 1, transform: notMounted ? 'translateY(-30px)' : 'translateY(0)' },
      'fade-left': { opacity: notMounted ? 0 : 1, transform: notMounted ? 'translateX(-30px)' : 'translateX(0)' },
      'fade-right': { opacity: notMounted ? 0 : 1, transform: notMounted ? 'translateX(30px)' : 'translateX(0)' },
      'scale-up': { opacity: notMounted ? 0 : 1, transform: notMounted ? 'scale(0.9)' : 'scale(1)' },
      'slide-up': { transform: notMounted ? 'translateY(100%)' : 'translateY(0)' }
    };

    return {
      ...animations[entranceAnimation],
      transitionDelay: `${delay}ms`
    };
  };

  // Get bento grid span
  const getBentoSpan = (size) => {
    switch (size) {
      case 'featured': return { gridColumn: 'span 2', gridRow: 'span 2' };
      case 'wide': return { gridColumn: 'span 2', gridRow: 'span 1' };
      case 'tall': return { gridColumn: 'span 1', gridRow: 'span 2' };
      case 'small': return { gridColumn: 'span 1', gridRow: 'span 1' };
      default: return { gridColumn: 'span 1', gridRow: 'span 1' };
    }
  };

  // Button component
  const CategoryButton = ({ text, isCardHovered }) => {
    const [btnHovered, setBtnHovered] = React.useState(false);

    const baseStyles = {
      display: 'inline-flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: `${buttonPaddingV}px ${buttonPaddingH}px`,
      fontSize: buttonFontSize + 'px',
      fontWeight: '500',
      fontFamily: `${titleFontFamily}, sans-serif`,
      textTransform: buttonTextTransform,
      letterSpacing: buttonTextTransform === 'uppercase' ? '0.05em' : '0em',
      borderRadius: buttonBorderRadius + 'px',
      cursor: 'pointer',
      border: 'none',
      background: 'none',
      transition: `all ${transitionDuration}ms ${transitionEasing}`,
      opacity: buttonHidden && !isCardHovered ? 0 : 1,
      transform: buttonHidden && !isCardHovered ? 'translateY(10px)' : 'translateY(0)',
      pointerEvents: buttonHidden && !isCardHovered ? 'none' : 'auto'
    };

    const styleVariants = {
      filled: {
        backgroundColor: btnHovered ? buttonHoverBackgroundColor : buttonBackgroundColor,
        color: btnHovered ? buttonHoverTextColor : buttonTextColor
      },
      outline: {
        backgroundColor: btnHovered ? buttonBackgroundColor : 'transparent',
        color: btnHovered ? buttonTextColor : buttonBackgroundColor,
        border: `1px solid ${buttonBackgroundColor}`
      },
      ghost: {
        backgroundColor: btnHovered ? `${buttonBackgroundColor}20` : 'transparent',
        color: buttonBackgroundColor
      },
      underline: {
        backgroundColor: 'transparent',
        color: buttonBackgroundColor,
        textDecoration: 'underline',
        textUnderlineOffset: '4px'
      }
    };

    return (
      <button
        style={{ ...baseStyles, ...styleVariants[buttonStyle] }}
        onMouseEnter={() => setBtnHovered(true)}
        onMouseLeave={() => setBtnHovered(false)}
        aria-label={text}
      >
        {text}
      </button>
    );
  };

  // Render single category card
  const renderCard = (category, index) => {
    const isHovered = hoveredIndex === index;
    const contentAlign = getContentAlignment(contentPosition);
    const entranceStyles = getEntranceStyles(index);
    const cardHoverStyles = getCardHoverStyles(isHovered);
    const imageHoverStyles = getImageHoverStyles(isHovered);
    const imageBaseStyles = getImageBaseStyles();
    const bentoSpan = displayMode === 'bento' ? getBentoSpan(category.size) : {};

    const isOverlayLayout = cardLayout === 'overlay' || cardLayout === 'image-only';
    const isSplitLayout = ['image-left', 'image-right', 'image-top', 'image-bottom'].includes(cardLayout);
    const isHorizontalSplit = ['image-left', 'image-right'].includes(cardLayout);

    // Calculate card height for carousel
    const computedHeight = displayMode === 'carousel' 
      ? cardHeight === 'auto' ? 'auto' : `${cardHeight}px`
      : cardHeight === 'auto' ? 'auto' : `${cardHeight}px`;

    return (
      <div
        key={index}
        style={{
          position: 'relative',
          display: 'flex',
          flexDirection: isHorizontalSplit 
            ? (cardLayout === 'image-left' ? 'row' : 'row-reverse')
            : (cardLayout === 'image-top' ? 'column' : 'column-reverse'),
          backgroundColor: cardBackgroundColor,
          borderRadius: cardBorderRadius + 'px',
          overflow: 'hidden',
          border: `1px solid ${cardBorderColor}`,
          cursor: 'pointer',
          transition: `all ${transitionDuration}ms ${transitionEasing}`,
          height: computedHeight,
          minWidth: displayMode === 'carousel' ? carouselCardWidth + 'px' : undefined,
          flexShrink: displayMode === 'carousel' ? 0 : undefined,
          ...bentoSpan,
          ...entranceStyles,
          ...cardHoverStyles
        }}
        onMouseEnter={() => setHoveredIndex(index)}
        onMouseLeave={() => setHoveredIndex(null)}
      >
        {/* Image Section */}
        {cardLayout !== 'content-only' && (
          <div
            style={{
              position: isOverlayLayout ? 'absolute' : 'relative',
              top: 0,
              left: 0,
              width: isOverlayLayout ? '100%' : (isHorizontalSplit ? `${imageSplit}%` : '100%'),
              height: isOverlayLayout ? '100%' : (isHorizontalSplit ? '100%' : `${imageSplit}%`),
              overflow: 'hidden',
              zIndex: 1
            }}
          >
            <img
              src={category.image || 'https://via.placeholder.com/600x400?text=Category'}
              alt={category.title || 'Category'}
              style={{
                width: '100%',
                height: '100%',
                objectFit: imageObjectFit,
                objectPosition: imageObjectPosition,
                transition: `all ${transitionDuration}ms ${transitionEasing}`,
                ...imageBaseStyles,
                ...imageHoverStyles
              }}
            />

            {/* Pattern Overlay */}
            {patternType !== 'none' && (
              <div
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  width: '100%',
                  height: '100%',
                  backgroundImage: getPatternCSS(patternType, patternColor, patternSize),
                  backgroundSize: getPatternSizeCSS(patternType, patternSize),
                  opacity: patternOpacity,
                  pointerEvents: 'none',
                  zIndex: 2
                }}
              />
            )}

            {/* Gradient/Color Overlay */}
            {showOverlay && isOverlayLayout && (
              <div
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  width: '100%',
                  height: '100%',
                  ...getOverlayCSS(overlayType, overlayColor, overlayOpacity, overlayGradientEnd, isHovered),
                  transition: `all ${transitionDuration}ms ${transitionEasing}`,
                  pointerEvents: 'none',
                  zIndex: 3
                }}
              />
            )}
          </div>
        )}

        {/* Content Section */}
        {cardLayout !== 'image-only' && (
          <div
            style={{
              position: isOverlayLayout ? 'absolute' : 'relative',
              top: 0,
              left: 0,
              width: isOverlayLayout ? '100%' : (isHorizontalSplit ? `${100 - imageSplit}%` : '100%'),
              height: isOverlayLayout ? '100%' : (isHorizontalSplit ? '100%' : `${100 - imageSplit}%`),
              display: 'flex',
              flexDirection: 'column',
              padding: contentPadding + 'px',
              boxSizing: 'border-box',
              zIndex: 10,
              direction: textDirection,
              ...contentAlign,
              transform: contentHoverEffect === 'slide-up' && isHovered && !prefersReducedMotion
                ? 'translateY(-8px)'
                : contentHoverEffect === 'slide-down' && isHovered && !prefersReducedMotion
                  ? 'translateY(8px)'
                  : contentHoverEffect === 'scale' && isHovered && !prefersReducedMotion
                    ? 'scale(1.02)'
                    : 'none',
              opacity: contentHoverEffect === 'fade-in' ? (isHovered ? 1 : 0.85) : 1,
              transition: `all ${transitionDuration}ms ${transitionEasing}`
            }}
          >
            {/* Tag */}
            {showTag && category.tag && (
              <span
                style={{
                  display: 'inline-block',
                  padding: '4px 10px',
                  backgroundColor: tagBackgroundColor,
                  color: tagTextColor,
                  fontSize: tagFontSize + 'px',
                  fontWeight: '500',
                  fontFamily: `${titleFontFamily}, sans-serif`,
                  textTransform: tagTextTransform,
                  letterSpacing: '0.05em',
                  borderRadius: '4px',
                  marginBottom: '12px',
                  alignSelf: contentAlign.alignItems
                }}
              >
                {category.tag}
              </span>
            )}

            {/* Title */}
            <h3
              style={{
                margin: 0,
                marginBottom: '8px',
                color: isOverlayLayout ? titleColor : '#212529',
                fontSize: titleFontSize + 'px',
                fontWeight: titleFontWeight,
                fontFamily: `${titleFontFamily}, sans-serif`,
                letterSpacing: titleLetterSpacing,
                textTransform: titleTextTransform,
                lineHeight: 1.2,
                textAlign: contentAlign.textAlign
              }}
            >
              {category.title || 'Category'}
            </h3>

            {/* Subtitle */}
            {showSubtitle && category.subtitle && (
              <p
                style={{
                  margin: 0,
                  marginBottom: '8px',
                  color: isOverlayLayout ? subtitleColor : '#495057',
                  fontSize: subtitleFontSize + 'px',
                  fontWeight: subtitleFontWeight,
                  fontFamily: `${titleFontFamily}, sans-serif`,
                  lineHeight: 1.5,
                  textAlign: contentAlign.textAlign,
                  opacity: subtitleHidden && !isHovered ? 0 : 1,
                  transform: subtitleHidden && !isHovered ? 'translateY(10px)' : 'translateY(0)',
                  transition: `all ${transitionDuration}ms ${transitionEasing}`,
                  maxHeight: subtitleHidden && !isHovered ? 0 : '100px',
                  overflow: 'hidden'
                }}
              >
                {category.subtitle}
              </p>
            )}

            {/* Product Count */}
            {showProductCount && category.count !== undefined && (
              <span
                style={{
                  color: isOverlayLayout ? countColor : '#6C757D',
                  fontSize: (subtitleFontSize - 1) + 'px',
                  fontWeight: '400',
                  fontFamily: `${titleFontFamily}, sans-serif`,
                  marginBottom: showButton ? '16px' : '0'
                }}
              >
                {category.count} products
              </span>
            )}

            {/* Button */}
            {showButton && category.button && (
              <div style={{ marginTop: 'auto', paddingTop: '12px' }}>
                <CategoryButton text={category.button} isCardHovered={isHovered} />
              </div>
            )}
          </div>
        )}
      </div>
    );
  };

  // Carousel navigation
  const scrollCarousel = (direction) => {
    if (!carouselRef.current) return;
    const scrollAmount = carouselCardWidth + gap;
    const newPosition = direction === 'next' 
      ? carouselRef.current.scrollLeft + scrollAmount
      : carouselRef.current.scrollLeft - scrollAmount;
    carouselRef.current.scrollTo({ left: newPosition, behavior: 'smooth' });
  };

  // Empty state
  if (categories.length === 0) {
    return (
      <div
        className="category-cards-pro"
        style={{
          backgroundColor: containerBackgroundColor,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          minHeight: '300px',
          padding: '40px',
          textAlign: 'center',
          color: '#71717A',
          fontFamily: `${titleFontFamily}, sans-serif`
        }}
      >
        <div>
          <p style={{ fontSize: '18px', marginBottom: '8px', color: '#3F3F46' }}>No categories configured</p>
          <p style={{ fontSize: '14px', opacity: 0.7 }}>Add category data in JSON format to display cards</p>
        </div>
      </div>
    );
  }

  // Grid Layout
  if (displayMode === 'grid') {
    return (
      <div
        className="category-cards-pro"
        style={{
          backgroundColor: containerBackgroundColor,
          padding: gap + 'px',
          direction: textDirection
        }}
      >
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: `repeat(${columns}, 1fr)`,
            gap: gap + 'px'
          }}
        >
          {categories.map((category, index) => renderCard(category, index))}
        </div>
      </div>
    );
  }

  // Bento Layout
  if (displayMode === 'bento') {
    return (
      <div
        className="category-cards-pro"
        style={{
          backgroundColor: containerBackgroundColor,
          padding: gap + 'px',
          direction: textDirection
        }}
      >
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: `repeat(${columns}, 1fr)`,
            gridAutoRows: cardHeight === 'auto' ? 'auto' : `${parseInt(cardHeight) / 2}px`,
            gap: gap + 'px'
          }}
        >
          {categories.map((category, index) => renderCard(category, index))}
        </div>
      </div>
    );
  }

  // Carousel Layout
  if (displayMode === 'carousel') {
    return (
      <div
        className="category-cards-pro"
        style={{
          backgroundColor: containerBackgroundColor,
          padding: `${gap}px 0`,
          position: 'relative',
          direction: textDirection
        }}
      >
        {/* Carousel Track */}
        <div
          ref={carouselRef}
          style={{
            display: 'flex',
            gap: gap + 'px',
            overflowX: 'auto',
            scrollBehavior: 'smooth',
            scrollSnapType: 'x mandatory',
            padding: `0 ${gap}px`,
            scrollbarWidth: 'none',
            msOverflowStyle: 'none'
          }}
        >
          {categories.map((category, index) => (
            <div key={index} style={{ scrollSnapAlign: 'start' }}>
              {renderCard(category, index)}
            </div>
          ))}
        </div>

        {/* Navigation Arrows */}
        {carouselShowArrows && (
          <>
            <button
              onClick={() => scrollCarousel('prev')}
              aria-label="Previous"
              style={{
                position: 'absolute',
                left: '8px',
                top: '50%',
                transform: 'translateY(-50%)',
                width: '40px',
                height: '40px',
                borderRadius: '50%',
                backgroundColor: '#FFFFFF',
                border: `1px solid ${cardBorderColor}`,
                boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: '18px',
                color: '#212529',
                transition: `all ${transitionDuration}ms ${transitionEasing}`,
                zIndex: 20
              }}
            >
              {isRTL ? '→' : '←'}
            </button>
            <button
              onClick={() => scrollCarousel('next')}
              aria-label="Next"
              style={{
                position: 'absolute',
                right: '8px',
                top: '50%',
                transform: 'translateY(-50%)',
                width: '40px',
                height: '40px',
                borderRadius: '50%',
                backgroundColor: '#FFFFFF',
                border: `1px solid ${cardBorderColor}`,
                boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: '18px',
                color: '#212529',
                transition: `all ${transitionDuration}ms ${transitionEasing}`,
                zIndex: 20
              }}
            >
              {isRTL ? '←' : '→'}
            </button>
          </>
        )}
      </div>
    );
  }

  return null;
}
